const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define northern part of Lake Eyre
  const lakeEyreNorth = ee.Geometry.Polygon([
    [[136.9, -28.2], [137.7, -28.2], [137.7, -28.8], [136.9, -28.8], [136.9, -28.2]]
  ]);

  const date1 = '2025-06-20';
  const date2 = '2025-09-15';

  // 2. Function to calculate water area
  function getWaterArea(startDate, endDate, geometry) {
    // Try Sentinel-2
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    const size = col.size().getInfo();
    console.log(`Images for ${startDate}: ${size}`);

    if (size === 0) {
      // Fallback to Landsat 9
      col = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(startDate, endDate);
      const sizeLandsat = col.size().getInfo();
      console.log(`Landsat fallback: ${sizeLandsat}`);
      if (sizeLandsat === 0) return null;
    }

    // Get median composite
    const img = col.median();

    // Calculate MNDWI for water detection
    let mndwi;
    if (col.first().bandNames().contains('B3').getInfo()) {
      // Sentinel-2: MNDWI = (Green - SWIR) / (Green + SWIR)
      mndwi = img.normalizedDifference(['B3', 'B11']);
    } else {
      // Landsat: MNDWI = (Green - SWIR1) / (Green + SWIR1)
      mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']);
    }

    // Water mask (MNDWI > 0)
    const waterMask = mndwi.gt(0);

    // Count water pixels
    const stats = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    const waterPixels = stats.get(Object.keys(stats.getInfo())[0]);
    return waterPixels !== null ? waterPixels.getInfo() : null;
  }

  // 3. Calculate water extent for both dates
  const waterJune = getWaterArea(date1, ee.Date(date1).advance(3, 'day').format('YYYY-MM-dd').getInfo(), lakeEyreNorth);

  if (waterJune === null) {
    console.log("No data for June 2025.");
    console.log("<answer>C1</answer>");
    return;
  }

  const waterSept = getWaterArea(date2, ee.Date(date2).advance(3, 'day').format('YYYY-MM-dd').getInfo(), lakeEyreNorth);

  if (waterSept === null) {
    console.log("No data for September 2025.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Validation
  console.log(`Water pixels June 2025: ${waterJune}`);
  console.log(`Water pixels Sept 2025: ${waterSept}`);

  if (waterJune === undefined || waterSept === undefined || 
      isNaN(waterJune) || isNaN(waterSept)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Compare and answer
  if (waterSept > waterJune) {
    console.log("Water extent increased");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent did not increase");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
